import torch

# Load the dataset to understand input/output shapes
dataset = torch.load('dataset.pt')
print(f"Dataset type: {type(dataset)}")
print(f"Dataset keys: {dataset.keys() if isinstance(dataset, dict) else 'not a dict'}")
if isinstance(dataset, dict):
    for k, v in dataset.items():
        if isinstance(v, torch.Tensor):
            print(f"{k}: shape={v.shape}, dtype={v.dtype}")
        else:
            print(f"{k}: {type(v)}")
else:
    print(f"Dataset is a {type(dataset)}")
    if isinstance(dataset, (list, tuple)):
        print(f"Length: {len(dataset)}")
        for i, item in enumerate(dataset[:2]):
            if isinstance(item, torch.Tensor):
                print(f"Item {i}: shape={item.shape}, dtype={item.dtype}")
EOF
